/**
 ******************************************************************************
 * @file    jack_ports.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) in the PD6 RTOS port (Sep 2026) for Jack's storage task;
 *          Brendon (integrator) made effect-file jobs resumable (30 Oct 2026, with an AI coding assistant).
 * @brief   FATFS implementation of PD5b_Jack/Interfaces/storage_port.h.
 *
 * Owner: Jack McMillan — Audio input & memory (PD6).
 *
 * RTOS role: helpers for JackStorageTask only (owner-task pattern, lecture 07
 * slide 22). Every f_*() call in the firmware is either here or in
 * jack_audio_sd.c's storage task, never anywhere else.
 *
 * What is open at a time: at most TWO files, because FatFs here has two
 * lock slots (_FS_LOCK 2): s_file (recording, playback, or the recording an
 * effect-file job reads) and s_fx_dst (the effect file being made). The root
 * iterator s_root_dir (the File list scan) takes no slot.
 *
 * A close that fails can keep its lock slot (FatFs frees the slot only
 * after a good f_sync inside f_close). Every close here that fails sets
 * s_remount_needed; JackStorageTask takes it (JackPorts_TakeRemountNeeded)
 * and remounts quietly, which empties the lock table, before it opens,
 * unlinks or renames anything else.
 *
 * Words: FATFS = the FAT file-system library; SDIO = the STM32's SD-card
 * bus; a lock slot = FatFs's note of one open file; a cluster = the unit in
 * which FAT hands out space (csize sectors of 512 bytes); CMD13 = the SD
 * command "send status". CR1 is a subsystem requirement from our Prototype
 * Design 2 (PD2): write fast enough to drop no audio (PD5b_Jack/VERIFICATION.md
 * Part 5).
 ******************************************************************************/
#include "jack_ports.h"
#include "cmsis_os2.h"
#include "fatfs.h"
#include "bsp_driver_sd.h"          /* BSP_SD_ReadBlocks_DMA for JackPorts_ReadProbe */
#include <string.h>

/* JackPorts_Expand needs f_expand, which pre-allocates each recording in one
 * piece so no free space has to be found in the FAT while it records (CR1).
 * The switch lives in FATFS/Target/ffconf.h, which CubeMX writes: stop the
 * build if a regeneration ever turns it off. */
#if !_USE_EXPAND
#error "_USE_EXPAND is 0: enable it in CubeMX (FATFS -> Set Defines -> USE_EXPAND = Enabled)"
#endif

static FIL      s_file;
static uint8_t  s_open = 0U;
static FIL      s_fx_dst;                   /* the effect file being made (storage_port.h group 3) */
static uint8_t  s_fx_open = 0U;
static uint8_t  s_remount_needed = 0U;      /* a close failed: a lock slot may be kept until a remount */

/* The root iterator (storage_port.h group 2). The root folder takes no
 * FatFs lock slot (only sub-folders do: ff.c f_opendir), so the iterator
 * can stay open between JackStorageTask's loop passes while a file is
 * recorded or played. Static, so a scan step costs no stack for them. */
static DIR      s_root_dir;
static FILINFO  s_root_info;
static uint8_t  s_root_open = 0U;

extern SD_HandleTypeDef hsd;        /* CubeMX, main.c — for the liveness probe only */

/* The old mapping, for the recording / playback calls: every FRESULT it
 * does not name becomes on_error (a card fault for the caller). */
static storage_result_t fr_to_result(FRESULT fr, storage_result_t on_error)
{
    switch (fr) {
        case FR_OK:        return STORAGE_OK;
        case FR_NO_FILE:
        case FR_NO_PATH:   return STORAGE_NOT_FOUND;
        case FR_INVALID_PARAMETER:
        case FR_INVALID_OBJECT: return STORAGE_INVALID_ARG;
        case FR_NO_FILESYSTEM:  return STORAGE_CORRUPT;
        default:           return on_error;
    }
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): fr_to_fx_result() */
/* The mapping for the calls by path (storage_port.h group 3). Only a
 * disk-level error is the card's fault: disk_error (READ_FAIL or WRITE_FAIL,
 * by the direction of the call). The old mapping sent every other FRESULT to
 * WRITE_FAIL too, which greys out REC and PLAY for a problem that is not the
 * card's: a read-only old file (FR_DENIED), a root FILE named FX
 * (FR_NO_PATH / FR_EXIST), an open file (FR_LOCKED). Those are REFUSED here,
 * and a leaked lock slot (FR_TOO_MANY_OPEN_FILES) is NO_SLOT, which a
 * remount clears. */
static storage_result_t fr_to_fx_result(FRESULT fr, storage_result_t disk_error)
{
    switch (fr) {
        case FR_OK:                  return STORAGE_OK;
        case FR_NO_FILE:
        case FR_NO_PATH:             return STORAGE_NOT_FOUND;
        case FR_DISK_ERR:
        case FR_NOT_READY:
        case FR_NOT_ENABLED:         /* no volume: unmounted, or the last mount failed */
        case FR_INT_ERR:             return disk_error;
        case FR_TOO_MANY_OPEN_FILES: return STORAGE_NO_SLOT;
        default:                     return STORAGE_REFUSED;
    }
}

/* ------------------------------ file open/close -------------------------- */
/* FA_CREATE_ALWAYS: a new file, or an existing one cut to 0 bytes (REC99.WAV
 * is used again once all 100 recording names exist). */
storage_result_t JackPorts_OpenWrite(const char *name)
{
    if (name == NULL) return STORAGE_INVALID_ARG;
    if (s_open) JackPorts_Close();
    FRESULT fr = f_open(&s_file, name, FA_CREATE_ALWAYS | FA_WRITE);
    if (fr != FR_OK) return fr_to_result(fr, STORAGE_WRITE_FAIL);
    s_open = 1U;
    return STORAGE_OK;
}

/* FA_OPEN_EXISTING: no create, no truncation, so the file keeps its size and
 * clusters. A fresh f_open also clears FatFs's sticky error flag. */
storage_result_t JackPorts_OpenWriteExisting(const char *name)
{
    if (name == NULL) return STORAGE_INVALID_ARG;
    if (s_open) JackPorts_Close();
    FRESULT fr = f_open(&s_file, name, FA_WRITE | FA_OPEN_EXISTING);
    if (fr != FR_OK) return fr_to_result(fr, STORAGE_WRITE_FAIL);
    s_open = 1U;
    return STORAGE_OK;
}

storage_result_t JackPorts_OpenRead(const char *name)
{
    if (name == NULL) return STORAGE_INVALID_ARG;
    if (s_open) JackPorts_Close();
    FRESULT fr = f_open(&s_file, name, FA_READ);
    if (fr != FR_OK) return fr_to_result(fr, STORAGE_READ_FAIL);
    s_open = 1U;
    return STORAGE_OK;
}

void JackPorts_Close(void)
{
    if (!s_open) return;
    s_open = 0U;
    if (f_close(&s_file) != FR_OK) s_remount_needed = 1U;    /* also on the recording path */
}

uint8_t JackPorts_TakeRemountNeeded(void)
{
    uint8_t needed = s_remount_needed;
    s_remount_needed = 0U;
    return needed;
}

storage_result_t JackPorts_Seek(uint32_t offset)
{
    if (!s_open) return STORAGE_INVALID_ARG;
    return fr_to_result(f_lseek(&s_file, (FSIZE_t)offset), STORAGE_WRITE_FAIL);
}

/* Reserve the whole recording as one contiguous run of clusters before it is
 * written (opt 1 = allocate now), so no free space has to be found in the
 * FAT while the recording runs. A failure (a fragmented card) is not an
 * error for the caller: the recording then allocates as it goes. */
storage_result_t JackPorts_Expand(uint32_t bytes)
{
    if (!s_open) return STORAGE_INVALID_ARG;
    return fr_to_result(f_expand(&s_file, (FSIZE_t)bytes, 1), STORAGE_FULL);
}

storage_result_t JackPorts_Truncate(void)
{
    if (!s_open) return STORAGE_INVALID_ARG;
    return fr_to_result(f_truncate(&s_file), STORAGE_WRITE_FAIL);
}

storage_result_t JackPorts_Sync(void)
{
    if (!s_open) return STORAGE_INVALID_ARG;
    return fr_to_result(f_sync(&s_file), STORAGE_WRITE_FAIL);
}

uint32_t JackPorts_FileSize(void)
{
    return s_open ? (uint32_t)f_size(&s_file) : 0U;
}

uint8_t JackPorts_Exists(const char *name)
{
    if (name == NULL) return 0U;
    return (f_stat(name, NULL) == FR_OK) ? 1U : 0U;
}

/* ------------------------------ storage_port.h --------------------------- */
/* One timed f_write: it blocks JackStorageTask until the card has the data.
 * The RTOS tick is 1 ms, so write_ms is in milliseconds. A write that
 * took longer than JACK_PORTS_SLOW_WRITE_MS is complete but reported SLOW;
 * recording_session stops the recording after 3 of those in a row. */
storage_result_t Storage_WriteChunk(const uint8_t *data, size_t len)
{
    if (data == NULL || len == 0U) return STORAGE_INVALID_ARG;
    if (!s_open) return STORAGE_WRITE_FAIL;

    UINT bw = 0;
    uint32_t t0 = osKernelGetTickCount();
    FRESULT fr = f_write(&s_file, data, (UINT)len, &bw);
    uint32_t write_ms = osKernelGetTickCount() - t0;

    if (fr != FR_OK) {
        return fr_to_result(fr, STORAGE_WRITE_FAIL);
    }
    if (bw < len) {
        return STORAGE_FULL;             /* FATFS writes short only when the volume is full */
    }
    if (write_ms > JACK_PORTS_SLOW_WRITE_MS) {
        return STORAGE_SLOW;             /* completed, but too slowly (CR1 risk) */
    }
    return STORAGE_OK;
}

storage_result_t Storage_ReadChunk(uint8_t *out, size_t max_len, size_t *out_read)
{
    if (out == NULL || out_read == NULL || max_len == 0U) return STORAGE_INVALID_ARG;
    *out_read = 0U;
    if (!s_open) return STORAGE_READ_FAIL;

    UINT br = 0;
    FRESULT fr = f_read(&s_file, out, (UINT)max_len, &br);
    if (fr != FR_OK) return STORAGE_READ_FAIL;
    *out_read = br;
    return STORAGE_OK;
}

/* Root directory listing: 8.3 names (_USE_LFN 0), regular files only.
 * Only file_index.c's old batch listings call it, and the firmware no longer
 * uses them: the File list now streams the root with the iterator below. */
storage_result_t Storage_ListDir(storage_dir_entry_t *out, size_t max_entries, size_t *out_count)
{
    if (out == NULL || out_count == NULL || max_entries == 0U) return STORAGE_INVALID_ARG;
    *out_count = 0U;

    DIR dir;
    FILINFO fno;
    if (f_opendir(&dir, "/") != FR_OK) return STORAGE_CORRUPT;

    storage_result_t res = STORAGE_OK;
    for (;;) {
        FRESULT fr = f_readdir(&dir, &fno);
        if (fr != FR_OK) { res = STORAGE_CORRUPT; break; }
        if (fno.fname[0] == '\0') break;                       /* end of directory */
        if (fno.fattrib & (AM_DIR | AM_HID | AM_SYS)) continue;
        if (*out_count >= max_entries) { res = STORAGE_TRUNCATED; break; }
        strncpy(out[*out_count].name, fno.fname, sizeof(out[*out_count].name) - 1U);
        out[*out_count].name[sizeof(out[*out_count].name) - 1U] = '\0';
        out[*out_count].size_bytes = (uint32_t)fno.fsize;
        (*out_count)++;
    }
    (void)f_closedir(&dir);
    return res;
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): the root iterator below */
/* ------------------------------ root iterator ---------------------------- */
storage_result_t Storage_DirOpen(void)
{
    Storage_DirClose();                                        /* one iterator: start again */
    if (f_opendir(&s_root_dir, "/") != FR_OK) return STORAGE_CORRUPT;
    s_root_open = 1U;
    return STORAGE_OK;
}

/* The next regular file of the root, skipping folders (the "FX" folder of
 * the effect files among them), hidden and system entries, as
 * Storage_ListDir does. */
storage_result_t Storage_DirNext(storage_dir_entry_t *entry)
{
    if (entry == NULL || !s_root_open) return STORAGE_CORRUPT;
    for (;;) {
        if (f_readdir(&s_root_dir, &s_root_info) != FR_OK) return STORAGE_CORRUPT;
        if (s_root_info.fname[0] == '\0') return STORAGE_NOT_FOUND;   /* end of the folder */
        if ((s_root_info.fattrib & (AM_DIR | AM_HID | AM_SYS)) == 0U) break;
    }
    strncpy(entry->name, s_root_info.fname, sizeof(entry->name) - 1U);
    entry->name[sizeof(entry->name) - 1U] = '\0';
    entry->size_bytes = (uint32_t)s_root_info.fsize;
    return STORAGE_OK;
}

void Storage_DirClose(void)
{
    if (!s_root_open) return;
    (void)f_closedir(&s_root_dir);
    s_root_open = 0U;
}

/* TEAM CODE (written by Brendon, integrator, 29-30 Oct 2026, best-ui): the calls by path below */
/* ------------------------------ files by path ---------------------------- */
/* f_stat opens nothing, so it needs no lock slot. */
storage_result_t Storage_Stat(const char *path, storage_stat_t *st)
{
    if (path == NULL || st == NULL) return STORAGE_INVALID_ARG;
    FILINFO info;
    FRESULT fr = f_stat(path, &info);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_READ_FAIL);
    st->size   = (uint32_t)info.fsize;
    st->fdate  = info.fdate;
    st->ftime  = info.ftime;
    st->is_dir = ((info.fattrib & AM_DIR) != 0U) ? 1U : 0U;
    return STORAGE_OK;
}

/* f_unlink writes the directory entry, frees the cluster chain in both FAT
 * copies and updates FSInfo: about four sector writes per existing file. */
storage_result_t Storage_Unlink(const char *path)
{
    if (path == NULL) return STORAGE_INVALID_ARG;
    return fr_to_fx_result(f_unlink(path), STORAGE_WRITE_FAIL);
}

/* The read/play file by path: the same s_file that Storage_ReadChunk reads. */
storage_result_t Storage_OpenRead(const char *path)
{
    if (path == NULL) return STORAGE_INVALID_ARG;
    JackPorts_Close();
    FRESULT fr = f_open(&s_file, path, FA_READ);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_READ_FAIL);
    s_open = 1U;
    return STORAGE_OK;
}

storage_result_t Storage_Seek(uint32_t offset)
{
    if (!s_open) return STORAGE_INVALID_ARG;
    return fr_to_fx_result(f_lseek(&s_file, (FSIZE_t)offset), STORAGE_READ_FAIL);
}

storage_result_t Storage_Close(void)
{
    if (!s_open) return STORAGE_OK;
    s_open = 0U;
    FRESULT fr = f_close(&s_file);
    if (fr != FR_OK) s_remount_needed = 1U;
    return fr_to_fx_result(fr, STORAGE_WRITE_FAIL);
}

/* The effect file being made: the second FIL, s_fx_dst. FA_CREATE_NEW
 * because J_CLEAN removed any old one: an existing file is FR_EXIST
 * (REFUSED), never silently overwritten. */
storage_result_t Storage_FxCreate(const char *path)
{
    if (path == NULL) return STORAGE_INVALID_ARG;
    (void)Storage_FxClose();
    FRESULT fr = f_open(&s_fx_dst, path, FA_CREATE_NEW | FA_WRITE);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_WRITE_FAIL);
    s_fx_open = 1U;
    return STORAGE_OK;
}

/* TEAM CODE (written by Brendon, 30 Oct 2026): the .TMP of a parked
 * effect-file job, opened again so the job can carry on writing it.
 * FA_OPEN_EXISTING, never FA_OPEN_ALWAYS: a missing .TMP must not come back
 * as an empty file with no header. f_size is what the directory entry says,
 * which f_close wrote when the job was parked. */
storage_result_t Storage_FxOpenExisting(const char *path, uint32_t *size)
{
    if (path == NULL || size == NULL) return STORAGE_INVALID_ARG;
    (void)Storage_FxClose();
    FRESULT fr = f_open(&s_fx_dst, path, FA_OPEN_EXISTING | FA_WRITE);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_READ_FAIL);
    *size = (uint32_t)f_size(&s_fx_dst);
    s_fx_open = 1U;
    return STORAGE_OK;
}

/* Not timed, unlike Storage_WriteChunk: one SD write can keep the card busy
 * for 250 ms, and that is no error for an effect file (nothing waits for it
 * in real time). Only a short write (the card is full) or an FRESULT error
 * fails it. */
storage_result_t Storage_FxWrite(const uint8_t *data, size_t len)
{
    if (data == NULL || len == 0U) return STORAGE_INVALID_ARG;
    if (!s_fx_open) return STORAGE_REFUSED;
    UINT bw = 0;
    FRESULT fr = f_write(&s_fx_dst, data, (UINT)len, &bw);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_WRITE_FAIL);
    return (bw < len) ? STORAGE_FULL : STORAGE_OK;
}

/* Never past the end: f_lseek there on a file open for writing makes the
 * file longer, with whatever the new clusters held (the host fake would
 * only clip, so such a bug would pass the tests and corrupt a file here). */
storage_result_t Storage_FxSeek(uint32_t offset)
{
    if (!s_fx_open) return STORAGE_REFUSED;
    if ((FSIZE_t)offset > f_size(&s_fx_dst)) return STORAGE_INVALID_ARG;
    return fr_to_fx_result(f_lseek(&s_fx_dst, (FSIZE_t)offset), STORAGE_WRITE_FAIL);
}

storage_result_t Storage_FxSync(void)
{
    if (!s_fx_open) return STORAGE_REFUSED;
    return fr_to_fx_result(f_sync(&s_fx_dst), STORAGE_WRITE_FAIL);
}

storage_result_t Storage_FxClose(void)
{
    if (!s_fx_open) return STORAGE_OK;
    s_fx_open = 0U;
    FRESULT fr = f_close(&s_fx_dst);
    if (fr != FR_OK) s_remount_needed = 1U;
    return fr_to_fx_result(fr, STORAGE_WRITE_FAIL);
}

/* f_mkdir zeroes the new folder's whole cluster (64 sectors on a 32 GB
 * card), so it is slow once per folder per card. FR_EXIST is fine only for
 * a folder; a FILE of that name, or a path through a file (FR_NO_PATH), is
 * REFUSED: the card itself is fine. */
storage_result_t Storage_Mkdir(const char *path)
{
    if (path == NULL) return STORAGE_INVALID_ARG;
    FRESULT fr = f_mkdir(path);
    if (fr == FR_OK) return STORAGE_OK;
    if (fr == FR_EXIST) {
        FILINFO info;
        if (f_stat(path, &info) == FR_OK && (info.fattrib & AM_DIR) != 0U) return STORAGE_OK;
        return STORAGE_REFUSED;
    }
    if (fr == FR_NO_PATH) return STORAGE_REFUSED;
    if (fr == FR_DENIED) {
        /* FR_DENIED: no free cluster for the new folder (a full card; f_mkdir
         * has just read the whole FAT looking for one), or a full FAT12/16
         * root. A full card is STORAGE_FULL, as in J_SPACE, so the job
         * engine stops the background instead of trying every folder again.
         * f_getfree costs no card time here (see Storage_FreeKb). */
        DWORD fre_clust = 0;
        FATFS *fs = NULL;
        if (f_getfree("", &fre_clust, &fs) == FR_OK && fre_clust == 0U) return STORAGE_FULL;
    }
    return fr_to_fx_result(fr, STORAGE_WRITE_FAIL);
}

storage_result_t Storage_Rename(const char *from, const char *to)
{
    if (from == NULL || to == NULL) return STORAGE_INVALID_ARG;
    return fr_to_fx_result(f_rename(from, to), STORAGE_WRITE_FAIL);
}

/* f_getfree costs no card time after the mount: FatFs keeps its count of
 * free clusters up to date on every allocate and free. */
storage_result_t Storage_FreeKb(uint32_t *free_kb)
{
    if (free_kb == NULL) return STORAGE_INVALID_ARG;
    DWORD fre_clust = 0;
    FATFS *fs = NULL;
    FRESULT fr = f_getfree("", &fre_clust, &fs);
    if (fr != FR_OK) return fr_to_fx_result(fr, STORAGE_READ_FAIL);
    if (fs == NULL) return STORAGE_READ_FAIL;
    *free_kb = (uint32_t)(((uint64_t)fre_clust * fs->csize) / 2U);     /* clusters x sectors x 512 B / 1024 */
    return STORAGE_OK;
}

/* ------------------------------ volume ----------------------------------- */
/* A card without a FAT volume (exFAT on cards over 32 GB, NTFS or blank) is
 * CORRUPT: the fault screen says "Format as FAT32". Any other failure (no
 * card, a sector that would not read) is READ_FAIL. */
storage_result_t JackPorts_Mount(void)
{
    /* ST's FatFs glue (ff_gen_drv.c) remembers "drive initialised" after the
     * first successful disk_initialize() and never calls the disk layer's
     * initialise again — so a second f_mount() after a card swap, a USB
     * hand-back or a failed first read would skip BSP_SD_Init() entirely and
     * fail on the first sector read (FR_DISK_ERR). Re-link the driver so
     * every mount brings the card up from scratch. */
    (void)FATFS_UnLinkDriver(SDPath);
    (void)FATFS_LinkDriver(&SD_Driver, SDPath);

    FRESULT fr = f_mount(&SDFatFS, (TCHAR const *)SDPath, 1);
    s_remount_needed = 0U;                  /* f_mount empties the lock table */
    if (fr != FR_OK) {
        /* TEAM CODE (written by Brendon, integrator, 30 Oct 2026, best-ui): the f_mount(NULL) below */
        /* f_mount registers SDFatFS BEFORE it reads the card, and a failed
         * mount leaves it registered: the next f_open or f_stat would then
         * try to mount the card by itself, behind JackStorageTask, which
         * thinks no card is mounted. Unregister it: after a failed mount
         * FatFs has no volume (FR_NOT_ENABLED) until the next JackPorts_Mount. */
        (void)f_mount(NULL, (TCHAR const *)SDPath, 0);
        return (fr == FR_NO_FILESYSTEM) ? STORAGE_CORRUPT : STORAGE_READ_FAIL;
    }
    return STORAGE_OK;
}

/* CMD13 backup check of a mounted card. The SD_DETECT pin (PA1, active-low,
 * measured 24 Sep 2026) is the storage task's primary signal; this asks the
 * card itself, and only while no transfer is in progress (idle only).
 *
 * The old version called ANY error "no card". But HAL_SD_GetCardState also
 * fails when the card DID answer and its status carries an error bit (the
 * HAL checks R1 against SDMMC_OCR_ERRORBITS): e.g. ILLEGAL_COMMAND, which a
 * card reports after a CMD12 it did not expect — exactly what the HAL's
 * SDIO error interrupt used to send (see sd_detect_override.c). A card that
 * answers is present. PD2 (CMD) has a pull-up, so an empty socket can only
 * give CTIMEOUT, never a response CRC error. */
jack_card_alive_t JackPorts_CardAlive(jack_alive_info_t *info)
{
    jack_alive_info_t d = { 0U };
    jack_card_alive_t a;

    if (hsd.State != HAL_SD_STATE_READY) {
        a = JACK_CARD_NOT_READY;                          /* never initialised (or mid-transfer): nothing sent */
    } else {
        hsd.ErrorCode = HAL_SD_ERROR_NONE;
        (void)HAL_SD_GetCardState(&hsd);                  /* returns 0, not an error code, on no response */
        d.err = hsd.ErrorCode;
        hsd.ErrorCode = HAL_SD_ERROR_NONE;                /* nothing stale for BrendonTask's MSC check */
        if (d.err == HAL_SD_ERROR_NONE) {
            a = JACK_CARD_ALIVE;
        } else if ((d.err & (HAL_SD_ERROR_CMD_RSP_TIMEOUT | HAL_SD_ERROR_TIMEOUT)) != 0U) {
            a = JACK_CARD_SILENT;
        } else {
            a = JACK_CARD_ANSWERED_ERR;
        }
    }
    if (info != NULL) *info = d;
    return a;
}

/* The path FatFs itself uses (BSP_SD_ReadBlocks_DMA), without the FatFs
 * layer: when CMD13 says nothing, a sector that still arrives proves the
 * card is there. */
storage_result_t JackPorts_ReadProbe(uint8_t *buf512)
{
    if (buf512 == NULL || ((uint32_t)buf512 & 0x3U) != 0U) return STORAGE_INVALID_ARG;
    return (BSP_SD_ReadBlocks_DMA((uint32_t *)buf512, 0U, 1U) == MSD_OK) ? STORAGE_OK : STORAGE_READ_FAIL;
}

void JackPorts_Unmount(void)
{
    JackPorts_Close();
    (void)Storage_FxClose();
    Storage_DirClose();
    (void)f_mount(NULL, (TCHAR const *)SDPath, 0);
    s_remount_needed = 0U;                  /* closes that failed with the card gone need no remount */
}

storage_result_t JackPorts_Capacity(uint32_t *total_kb, uint32_t *free_kb)
{
    if (total_kb == NULL || free_kb == NULL) return STORAGE_INVALID_ARG;
    DWORD fre_clust = 0;
    FATFS *fs = NULL;
    if (f_getfree("", &fre_clust, &fs) != FR_OK || fs == NULL || fs->n_fatent <= 2U) {
        *total_kb = 0U; *free_kb = 0U;
        return STORAGE_READ_FAIL;
    }
    /* cluster size in sectors x 512 B -> KB: (clusters * csize) / 2.
     * The FAT's first 2 entries are reserved, so n_fatent - 2 data clusters. */
    *total_kb = (uint32_t)(((uint64_t)(fs->n_fatent - 2U) * fs->csize) / 2U);
    *free_kb  = (uint32_t)(((uint64_t)fre_clust * fs->csize) / 2U);
    return STORAGE_OK;
}
